class Solution {
    private boolean check(String seg, String word, String revWord) {
        int k = word.length();
        if (seg.length() != k) return false;
        boolean forward = true, backward = true;
        for (int i = 0; i < k; i++) {
            if (seg.charAt(i) != ' ' && seg.charAt(i) != word.charAt(i)) forward = false;
            if (seg.charAt(i) != ' ' && seg.charAt(i) != revWord.charAt(i)) backward = false;
        }
        return forward || backward;
    }
    public boolean placeWordInCrossword(char[][] board, String word) {
        int m = board.length, n = board[0].length;
        String revWord = new StringBuilder(word).reverse().toString();
        for (int r = 0; r < m; r++) {
            StringBuilder seg = new StringBuilder();
            for (int c = 0; c <= n; c++) {
                if (c == n || board[r][c] == '#') {
                    if (check(seg.toString(), word, revWord)) return true;
                    seg.setLength(0);
                } else {
                    seg.append(board[r][c]);
                }
            }
        }
