var placeWordInCrossword = function(board, word) {
  const m = board.length, n = board[0].length;
  const k = word.length;
  const revWord = word.split('').reverse().join('');

  function match(seg) {
    if (seg.length !== k) return false;
    let forward = true, backward = true;
    for (let i = 0; i < k; i++) {
      if (seg[i] !== ' ' && seg[i] !== word[i]) forward = false;
      if (seg[i] !== ' ' && seg[i] !== revWord[i]) backward = false;
    }
    return forward || backward;
  }

  for (let r = 0; r < m; r++) {
    const rowStr = board[r].join('');
    for (const seg of rowStr.split('#')) {
      if (match(seg)) return true;
    }
  }
  for (let c = 0; c < n; c++) {
    let colStr = '';
    for (let r = 0; r < m; r++) colStr += board[r][c];
    for (const seg of colStr.split('#')) {
      if (match(seg)) return true;
    }
  }
  return false;
};
